import test from 'node:test';import assert from 'node:assert/strict';
import {makeSubjectAddress,makeCapabilityAddress,parseTinpAddress,NodeDirectory,RouteGraph,makeForwardEnvelope,forwardNext,SecurityProviderRegistry,TransportProviderRegistry,makeNoneTestSecurityProvider,makeHello,TinpRuntime,CapabilityRouter,toOppChpOffer,toOppChpAgreement,UdpTransport,decodeFrame,TINP_PROTOCOL} from '../src/index.mjs';

test('subject and capability addresses round-trip',()=>{const s=makeSubjectAddress({subjectId:'subject:杜衡界',nodeId:'node:laptop'});assert.equal(parseTinpAddress(s.uri).subjectId,'subject:杜衡界');const c=makeCapabilityAddress({capability:'rncs.state.sync',authorityScope:'candidate.read',payloadProfile:'application/json'});assert.equal(parseTinpAddress(c.uri).capability,'rncs.state.sync');});

test('node directory discovers compatible capability and expires stale nodes',()=>{let t=Date.parse('2026-09-08T09:00:00Z');const d=new NodeDirectory({clock:()=>new Date(t)});d.advertise({nodeId:'n1',subjectId:'s1',capabilities:['x'],authorityScopes:['read'],payloadProfiles:['application/json'],securityProfiles:['none-test'],ttlMs:100});assert.equal(d.findCapability('x',{authorityScope:'read'}).length,1);t+=101;assert.equal(d.findCapability('x').length,0);});

test('route graph selects lower-cost multi-hop path',()=>{const g=new RouteGraph().connect('a','b',{cost:1}).connect('b','c',{cost:1}).connect('a','c',{cost:9});const r=g.route('a','c');assert.deepEqual(r.path,['a','b','c']);assert.equal(r.cost,2);});

test('forward envelope is fail-closed on wrong hop and decrements ttl',()=>{const r=new RouteGraph().connect('a','b').connect('b','c').route('a','c');let e=makeForwardEnvelope({route:r,payloadType:'DATA',payload:{x:1},ttl:3});assert.throws(()=>forwardNext(e,'b'),x=>x.code==='FORWARD_WRONG_HOP');let x=forwardNext(e,'a');assert.equal(x.nextNodeId,'b');assert.equal(x.envelope.ttl,2);x=forwardNext(x.envelope,'b');assert.equal(x.nextNodeId,'c');assert.equal(x.envelope.ttl,1);assert.equal(forwardNext(x.envelope,'c').delivered,true);});

test('security provider registry rejects non-production-safe profile',()=>{const r=new SecurityProviderRegistry();r.register(makeNoneTestSecurityProvider());assert.throws(()=>r.requireProductionSafe('none-test'),e=>e.code==='SECURITY_PROVIDER_NOT_PRODUCTION_SAFE');});

test('transport provider registry selects by predicate',()=>{const r=new TransportProviderRegistry();r.register({id:'loopback',priority:1,kind:'memory'});r.register({id:'udp',priority:2,kind:'datagram'});assert.equal(r.choose(x=>x.kind==='datagram').id,'udp');});

test('session migration preserves subjects, authority and receipt continuity anchor',()=>{const router=new CapabilityRouter();router.register({providerId:'p',capabilities:['x'],payloadProfiles:['application/json'],authorityScopes:['read'],securityProfiles:['none-test'],handler:async()=>({ok:true})});const rt=new TinpRuntime({router});const a=makeHello({nodeId:'a',subjectId:'sa',payloadProfiles:['application/json'],capabilities:['x'],authorityScopes:['read']});const b=makeHello({nodeId:'b',subjectId:'sb',payloadProfiles:['application/json'],capabilities:['x'],authorityScopes:['read']});const g=rt.openSession({sourceHello:a,targetHello:b});const m=rt.migrateSession(g.sessionId,{newSourceNodeId:'a2'});assert.equal(m.grant.sourceSubjectId,'sa');assert.equal(m.grant.sourceNodeId,'a2');assert.deepEqual(m.grant.grantedScopes,['read']);assert.equal(m.migration.previousReceiptRoot,'0'.repeat(64));});

test('OPP CHP bridge emits schema-compatible offer shape and deterministic agreement',()=>{const a=makeHello({nodeId:'a',subjectId:'sa',capabilities:['x'],authorityScopes:['read']});const b=makeHello({nodeId:'b',subjectId:'sb',capabilities:['x','y'],authorityScopes:['read','write']});const oa=toOppChpOffer(a),ob=toOppChpOffer(b);assert.equal(oa.payload.evidencePolicy.minimumConfidence,0);const ag=toOppChpAgreement(oa,ob);assert.equal(ag.status,'accepted');assert.deepEqual(ag.sharedCapabilities,['x']);assert.deepEqual(ag.authorityScopes,['read']);assert.ok(ag.agreedProtocols.includes(TINP_PROTOCOL));});

test('three real UDP localhost nodes forward one TINP frame across two hops',async()=>{const a=await new UdpTransport().bind(),b=await new UdpTransport().bind(),c=await new UdpTransport().bind();try{const graph=new RouteGraph().connect('a','b').connect('b','c');let env=makeForwardEnvelope({route:graph.route('a','c'),payloadType:'DATA',payload:{message:'两跳'},ttl:4});const delivered=new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('timeout')),1500);c.onFrame(frame=>{try{assert.equal(frame.typeName,'FORWARD');const fin=forwardNext(frame.payload,'c');assert.equal(fin.delivered,true);assert.equal(frame.payload.payload.message,'两跳');clearTimeout(timer);resolve(frame.payload);}catch(e){reject(e);}});});b.onFrame(async frame=>{if(frame.error)return;const step=forwardNext(frame.payload,'b');await b.send('127.0.0.1',c.port,'FORWARD',step.envelope);});const first=forwardNext(env,'a');await a.send('127.0.0.1',b.port,'FORWARD',first.envelope);const got=await delivered;assert.deepEqual(got.trace,['a','b']);}finally{a.close();b.close();c.close();}});
